const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const titleFonts=['Montserrat','Pixelify Sans','Orbitron','Lora'];
export const titlePresets={clean:{name:'Clean',font:'Montserrat',fontSize:48,buttonFont:'Montserrat',buttonSize:14,align:'center',buttonStyle:'solid',accent:'#ab88d3',textColor:'#f4ede2'},arcade:{name:'Arcade',font:'Pixelify Sans',fontSize:64,buttonFont:'Pixelify Sans',buttonSize:21,align:'center',buttonStyle:'solid',accent:'#b7d77d',textColor:'#f5eccd'},story:{name:'Storybook',font:'Lora',fontSize:48,buttonFont:'Montserrat',buttonSize:14,align:'left',buttonStyle:'outline',accent:'#d5b77d',textColor:'#f6e6c5'},space:{name:'Space',font:'Orbitron',fontSize:43,buttonFont:'Orbitron',buttonSize:12,align:'center',buttonStyle:'outline',accent:'#80c4d8',textColor:'#e8f5f8'}};
export function titleDefaults(project){const saved=project.titleScreen||{};return{...titlePresets.clean,enabled:false,title:project.name,playLabel:'Play',settings:true,multiplayer:false,pages:[{id:'controls',title:'Controls',content:project.instructions||'Move with the arrow keys. Jump with Space. Use the mouse or touch to interact.'},{id:'credits',title:'Credits',content:project.indieExample?'A Playform Studio example.\nVisuals and sounds are included in the editable project.':'Made with Playform Studio.'}],links:[{id:'controls-link',label:'Controls',target:'page:controls',scope:'home'},{id:'credits-link',label:'Credits',target:'page:credits',scope:'home'}],...saved}}
export function renderTitleMenu(element,project,{onPlay,onFriends,onSettings}){
 const settings=titleDefaults(project),pages=Array.isArray(settings.pages)?settings.pages:[],links=Array.isArray(settings.links)?settings.links:[];
 const accent=/^#[\da-f]{6}$/i.test(settings.accent||'')?settings.accent:'#ab88d3';
 element.style.setProperty('--game-accent',accent);element.style.setProperty('--game-title-font',titleFonts.includes(settings.font)?settings.font:'Montserrat');element.style.setProperty('--game-button-font',titleFonts.includes(settings.buttonFont)?settings.buttonFont:'Montserrat');element.style.setProperty('--game-title-size',`${Math.max(24,Math.min(88,settings.fontSize||48))}px`);element.style.setProperty('--game-button-size',`${Math.max(11,Math.min(24,settings.buttonSize||14))}px`);element.style.setProperty('--game-text',/^#[\da-f]{6}$/i.test(settings.textColor||'')?settings.textColor:'#f4ede2');element.dataset.align=['left','right'].includes(settings.align)?settings.align:'center';element.dataset.buttonStyle=settings.buttonStyle==='outline'?'outline':'solid';element.style.backgroundImage=settings.artwork?`linear-gradient(#0d111944,#0d111966),url("${settings.artwork}")`:'';
 function navigate(target){if(target==='game')onPlay();else if(target==='settings')onSettings();else if(target==='friends')onFriends();else if(target==='home')render('home');else if(target.startsWith('page:'))render(target.slice(5));else if(/^https?:\/\//i.test(target))window.open(target,'_blank','noopener,noreferrer')}
 function render(id){const page=pages.find(p=>p.id===id),home=!page;const current=home?'home':page.id;const buttons=links.filter(link=>(link.scope||'home')===current&&(!link.target.startsWith('page:')||pages.some(p=>'page:'+p.id===link.target)));element.dataset.page=current;
  element.innerHTML=`<div class="game-title-card">${home&&settings.logo?`<img class="game-title-logo" src="${settings.logo}" alt="">`:''}<h1>${esc(home?settings.title||project.name:page.title)}</h1>${home&&settings.subtitle?`<p>${esc(settings.subtitle)}</p>`:''}${page?`<div class="title-page-content">${esc(page.content||'')}</div>`:''}<div class="game-title-buttons">${home?`<button class="title-play">${esc(settings.playLabel||'Play')}</button>${settings.multiplayer?'<button class="title-friends">Play with friends</button>':''}${settings.settings!==false?'<button class="title-settings">Settings</button>':''}`:''}${buttons.map((link,i)=>`<button data-title-link="${i}">${esc(link.label||'Open page')}</button>`).join('')}${home?'':'<button class="title-back">Back to title</button>'}</div></div>`;
  const play=element.querySelector('.title-play');if(play)play.onclick=onPlay;const friends=element.querySelector('.title-friends');if(friends){friends.title='Invite or join a friend';friends.onclick=onFriends};const options=element.querySelector('.title-settings');if(options)options.onclick=onSettings;const back=element.querySelector('.title-back');if(back)back.onclick=()=>render('home');element.querySelectorAll('[data-title-link]').forEach(button=>{const target=buttons[+button.dataset.titleLink].target||'home';button.onclick=()=>navigate(target)});
 }
 render('home');
}
export function titleDesignerMarkup(){return `<details class="title-designer-section" open><summary>Style & presets</summary><div class="title-preset-buttons">${Object.entries(titlePresets).map(([id,preset])=>`<button type="button" data-title-preset="${id}">${preset.name}</button>`).join('')}<button type="button" id="reset-title-design">Reset defaults</button></div><div class="game-size-grid"><label>Title font<select id="title-font">${titleFonts.map(font=>`<option>${font}</option>`).join('')}</select></label><label>Title size<input id="title-font-size" type="number" min="24" max="88"></label><label>Button font<select id="title-button-font">${titleFonts.map(font=>`<option>${font}</option>`).join('')}</select></label><label>Button size<input id="title-button-size" type="number" min="11" max="24"></label><label>Alignment<select id="title-align"><option value="center">Center</option><option value="left">Left</option><option value="right">Right</option></select></label><label>Button style<select id="title-button-style"><option value="solid">Solid</option><option value="outline">Outline</option></select></label><label>Text color<input type="color" id="title-text-color"></label></div></details><details class="title-designer-section"><summary>Pages & links</summary><div id="title-pages-editor"></div><div id="title-links-editor"></div></details>`}
export function bindTitleDesigner(dialog,project,settings,onReset,notify){
 const $=s=>dialog.querySelector(s);let pages=JSON.parse(JSON.stringify(settings.pages||[])),links=JSON.parse(JSON.stringify(settings.links||[])),selected=pages[0]?.id;
 const setStyle=preset=>{for(const[key,id]of Object.entries({font:'title-font',fontSize:'title-font-size',buttonFont:'title-button-font',buttonSize:'title-button-size',align:'title-align',buttonStyle:'title-button-style',textColor:'title-text-color',accent:'title-accent'}))$('#'+id).value=preset[key]??titlePresets.clean[key]};setStyle(settings);
 function renderPages(){const page=pages.find(p=>p.id===selected);$('#title-pages-editor').innerHTML=`<div class="title-editor-heading"><h3>Pages</h3><button id="add-title-page" type="button">＋ Page</button></div><select id="selected-title-page" aria-label="Edit title-screen page">${pages.map(p=>`<option value="${esc(p.id)}" ${p.id===selected?'selected':''}>${esc(p.title)}</option>`).join('')}</select>${page?`<label>Page title<input id="title-page-name" maxlength="60" value="${esc(page.title)}"></label><label>Page content<textarea id="title-page-content" maxlength="3000">${esc(page.content||'')}</textarea></label><button id="delete-title-page" type="button">Delete page</button>`:''}`;
  $('#selected-title-page').onchange=e=>{selected=e.target.value;renderPages()};$('#add-title-page').onclick=()=>{if(pages.length>=8){notify('A title screen can have up to 8 pages.');return}const title=prompt('Page title (About, Controls, Credits…)');if(!title?.trim())return;const page={id:crypto.randomUUID(),title:title.trim().slice(0,60),content:''};pages.push(page);selected=page.id;if(links.length<12)links.push({id:crypto.randomUUID(),label:page.title,target:'page:'+page.id,scope:'home'});renderPages();renderLinks()};
  if(page){$('#title-page-name').oninput=e=>{page.title=e.target.value};$('#title-page-content').oninput=e=>page.content=e.target.value;$('#delete-title-page').onclick=()=>{pages=pages.filter(p=>p!==page);links=links.filter(link=>link.target!=='page:'+page.id&&link.scope!==page.id);selected=pages[0]?.id;renderPages();renderLinks()}}
 }
 function renderLinks(){const targets=[['game','Start game'],['friends','Play with friends'],['settings','Settings'],['home','Main title'],...pages.map(p=>['page:'+p.id,p.title]),['url','Website link']];$('#title-links-editor').innerHTML=`<div class="title-editor-heading"><h3>Buttons & links</h3><button id="add-title-link" type="button">＋ Link</button></div>${links.map((link,i)=>`<div class="title-link-row" data-link-row="${i}"><label>Label<input data-link-label="${i}" maxlength="30" value="${esc(link.label)}"></label><label>Destination<select data-link-target="${i}">${targets.map(([value,label])=>`<option value="${esc(value)}"  ${(value===link.target||value==='url'&&/^https?:/.test(link.target))?'selected':''}>${esc(label)}</option>`).join('')}</select></label><label>Show on<select data-link-scope="${i}"><option value="home">Main title</option>${pages.map(p=>`<option value="${esc(p.id)}" ${p.id===link.scope?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label><div class="title-link-tools"><button type="button" data-link-up="${i}" aria-label="Move link up">↑</button><button type="button" data-link-down="${i}" aria-label="Move link down">↓</button><button type="button" data-link-delete="${i}" aria-label="Delete link">×</button></div>${/^https?:/.test(link.target)||link.target==='url'?`<label class="title-url-label">URL<input type="url" data-link-url="${i}" placeholder="https://example.com" value="${link.target==='url'?'':esc(link.target)}"></label>`:''}</div>`).join('')}`;
  $('#add-title-link').onclick=()=>{if(links.length>=12){notify('A title screen can have up to 12 custom links.');return}links.push({id:crypto.randomUUID(),label:'New button',target:'home',scope:'home'});renderLinks()};for(const[key,field]of [['label','label'],['scope','scope']])dialog.querySelectorAll(`[data-link-${key}]`).forEach(input=>input.oninput=()=>links[+input.dataset['link'+key[0].toUpperCase()+key.slice(1)]][field]=input.value);dialog.querySelectorAll('[data-link-target]').forEach(select=>select.onchange=()=>{links[+select.dataset.linkTarget].target=select.value;renderLinks()});dialog.querySelectorAll('[data-link-url]').forEach(input=>input.oninput=()=>links[+input.dataset.linkUrl].target=input.value);dialog.querySelectorAll('[data-link-delete]').forEach(button=>button.onclick=()=>{links.splice(+button.dataset.linkDelete,1);renderLinks()});for(const[key,direction]of [['up',-1],['down',1]])dialog.querySelectorAll(`[data-link-${key}]`).forEach(button=>button.onclick=()=>{const i=+button.dataset['link'+key[0].toUpperCase()+key.slice(1)],j=i+direction;if(j<0||j>=links.length)return;[links[i],links[j]]=[links[j],links[i]];renderLinks()})
 }
 dialog.querySelectorAll('[data-title-preset]').forEach(button=>button.onclick=()=>setStyle(titlePresets[button.dataset.titlePreset]));$('#reset-title-design').onclick=()=>{setStyle(titlePresets.clean);const fresh=titleDefaults({...project,titleScreen:null});pages=fresh.pages;links=fresh.links;selected=pages[0]?.id;$('#title-enabled').checked=true;$('#title-text').value=project.name;$('#title-subtitle').value='';$('#title-play-label').value='Play';$('#title-settings').checked=true;$('#title-multiplayer').checked=false;onReset();renderPages();renderLinks()};renderPages();renderLinks();
 return()=>{for(const link of links){if(!link.label.trim())throw Error('Name each menu button.');if(link.target==='url'||/^https?:/.test(link.target)&&!/^https?:\/\//i.test(link.target))throw Error('Enter a complete http:// or https:// website link.')}return{font:$('#title-font').value,fontSize:Math.max(24,Math.min(88,+$('#title-font-size').value||48)),buttonFont:$('#title-button-font').value,buttonSize:Math.max(11,Math.min(24,+$('#title-button-size').value||14)),align:$('#title-align').value,buttonStyle:$('#title-button-style').value,textColor:$('#title-text-color').value,pages,links}}
}
